import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.CDBtBf5v.js";const u=JSON.parse('{"title":"GOOSE 跨平台收发与自发自收","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/iec61850/goose-cross-platform.md","filePath":"guide/protocols/iec61850/goose-cross-platform.md","lastUpdated":1794013948000}'),d={name:"guide/protocols/iec61850/goose-cross-platform.md"};function o(n,e,r,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="goose-跨平台收发与自发自收" tabindex="-1">GOOSE 跨平台收发与自发自收 <a class="header-anchor" href="#goose-跨平台收发与自发自收" aria-label="Permalink to &quot;GOOSE 跨平台收发与自发自收&quot;">​</a></h1><p>本文说明 EMS Simulate 在 Linux 和 Windows 上如何发送、捕获和订阅 GOOSE，以及本机发出的报文在旧版 Linux 接收路径中被丢弃的原因。</p><p>GOOSE 使用以太网二层组播，协议 EtherType 为 <code>0x88B8</code>。发布器、订阅器和抓包器各自选择网卡。这里的<strong>自发自收</strong>指发布器和订阅器在同一台主机、同一块以太网网卡上运行，订阅器读取系统抓包接口提供的本机出站帧副本。选用发布时的实际网卡即可。模型加载后，GOOSE 可以独立于 MMS 连接运行，详见 <a href="./operation.html">IEC 61850 操作指南</a>。</p><h2 id="linux-与-windows-的实现差异" tabindex="-1">Linux 与 Windows 的实现差异 <a class="header-anchor" href="#linux-与-windows-的实现差异" aria-label="Permalink to &quot;Linux 与 Windows 的实现差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>Linux</th><th>Windows</th></tr></thead><tbody><tr><td>发布</td><td>由 <code>pyiec61850-ng</code> 调用 libiec61850，按发布配置构造并发送以太网帧</td><td>由 Scapy 构造以太网帧和 GOOSE 负载，通过 Npcap 发送</td></tr><tr><td>VLAN ID 为 <code>0</code></td><td>发布器仍生成 802.1Q 标签。VID 为 <code>0</code>，PCP 携带配置的优先级</td><td>发布器生成无标签帧。报文中没有 VLAN PCP 字段</td></tr><tr><td>VLAN ID 大于 <code>0</code></td><td>发布器生成带 VID 和 PCP 的 802.1Q 帧</td><td>Scapy 添加带 VID 和 PCP 的 <code>Dot1Q</code> 头。现场可在对端抓包确认网卡实际发出的标签</td></tr><tr><td>订阅和独立抓包</td><td><code>AF_PACKET</code> 原始套接字绑定指定网卡，使用 <code>ETH_P_ALL</code> 接收，并在应用内解析 EtherType</td><td>Scapy 在指定的 Npcap 适配器上抓取二层帧，再使用同一套 GOOSE 解析器</td></tr><tr><td>运行条件</td><td>后端进程在对应网络命名空间中具有 <code>CAP_NET_RAW</code>，并能看到目标网卡</td><td>安装并启用 Npcap。若安装时限制为仅管理员访问，后端需要相应权限</td></tr><tr><td>订阅历史中的 <code>timestamp</code></td><td>毫秒级 GOOSE 事件时标，取自帧内字段 <code>t</code></td><td>毫秒级本机捕获时刻</td></tr></tbody></table><p>两端都用本机捕获时刻更新订阅的最后接收时间。抓包详情会区分帧内事件时标与捕获时刻。同一状态的周期重发通常保留事件时标，接收计数和 <code>sqNum</code> 更适合判断订阅是否持续收到报文。</p><p>原先的 libiec61850 Windows 接收路径曾出现接口启动后未收到回调的情况。当前二层收发使用 Scapy/Npcap。安装要求和迁移背景可参阅以下资料。 <a href="https://npcap.com/guide/npcap-users-guide.html" target="_blank" rel="noreferrer">Npcap 用户指南</a> · <a href="./../../../changelog/iec61850/goose/04-receive-history-capture-refactoring.html">GOOSE 接收、DataSet 历史与抓包链路重构</a></p><h2 id="linux-旧接收路径为何漏掉本机帧" tabindex="-1">Linux 旧接收路径为何漏掉本机帧 <a class="header-anchor" href="#linux-旧接收路径为何漏掉本机帧" aria-label="Permalink to &quot;Linux 旧接收路径为何漏掉本机帧&quot;">​</a></h2><p>两种帧的差别出现在源 MAC 之后。下表中的偏移从以太网帧首字节开始计算。</p><table tabindex="0"><thead><tr><th>帧格式</th><th>偏移 12–13</th><th>偏移 14–15</th><th>偏移 16–17</th><th>APPID 起始偏移</th></tr></thead><tbody><tr><td>无标签 GOOSE</td><td><code>0x88B8</code></td><td>APPID</td><td>GOOSE 长度</td><td>14</td></tr><tr><td>单层 802.1Q GOOSE</td><td><code>0x8100</code></td><td>VLAN TCI，含 PCP、DEI 和 VID</td><td><code>0x88B8</code></td><td>18</td></tr></tbody></table><p>例如 VID 为 <code>0</code>、PCP 为 <code>4</code>、DEI 为 <code>0</code> 时，带标签的帧从偏移 12 开始可见 <code>81 00 80 00 88 B8</code>。旧过滤器读到的是前两个字节 <code>81 00</code>。</p><ol><li>Linux 发布端调用 <code>GoosePublisher_create()</code>。libiec61850 v1.6.1 通过该入口启用 VLAN 标签，因此默认 VID 为 <code>0</code> 时，帧仍以 <code>0x8100</code> 作为外层 EtherType。 <a href="https://github.com/mz-automation/libiec61850/blob/v1.6.1/src/goose/goose_publisher.c" target="_blank" rel="noreferrer">libiec61850 v1.6.1 发布端源码</a></li><li>Linux 可将本机发送的帧以 <code>PACKET_OUTGOING</code> 类型交给同一接口上的其他抓包套接字。本机可以通过这份副本观察发布流量，无需等待交换机把帧送回。 <a href="https://man7.org/linux/man-pages/man7/packet.7.html" target="_blank" rel="noreferrer">Linux packet(7)</a></li><li>旧订阅路径使用 libiec61850 的 Linux GOOSE 接收器。其内核过滤器只比较偏移 12–13 的值与 <code>0x88B8</code>。当出站副本保留 802.1Q 头时，该位置是 <code>0x8100</code>，帧在到达 GOOSE 解析和订阅匹配之前就被丢弃。这解释了同一网卡上独立抓包有数据、订阅计数却为零的现象。 <a href="https://github.com/mz-automation/libiec61850/blob/v1.6.1/hal/ethernet/linux/ethernet_linux.c" target="_blank" rel="noreferrer">libiec61850 v1.6.1 Linux 接收过滤器源码</a></li></ol><p>Windows 默认 VID 为 <code>0</code> 时构造的是无标签帧，接收也走 Npcap 路径。相同的发布参数在两个系统上可能生成不同的以太网头。</p><h2 id="修复后的-linux-接收流程" tabindex="-1">修复后的 Linux 接收流程 <a class="header-anchor" href="#修复后的-linux-接收流程" aria-label="Permalink to &quot;修复后的 Linux 接收流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GOOSE Publisher → 指定以太网网卡 → 本机出站帧副本</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>外部 GOOSE 组播 → 同一网卡 ───────→ AF_PACKET / ETH_P_ALL</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                              识别无标签或单层 802.1Q</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                                 解析 GOOSE 头和 PDU</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                           匹配启用的订阅 → 更新数据和历史</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ul><li>接收套接字按网卡绑定，并使用套接字级的 <code>PACKET_MR_ALLMULTI</code> 接收该网卡上的外部二层组播。套接字关闭时，内核清理这项成员资格。 <a href="https://man7.org/linux/man-pages/man7/packet.7.html" target="_blank" rel="noreferrer">Linux packet(7)</a></li><li>应用识别帧头是否含单层 <code>0x8100</code> 标签，再从正确位置读取 <code>0x88B8</code> 和 APPID。Linux 发布端继续使用 libiec61850，现有的 VID 和优先级配置仍可使用。</li><li>订阅器仅处理已启用、<code>goCbRef</code> 完全一致的订阅。配置了 APPID 或目的 MAC 时，对应字段也必须相同。独立抓包有数据只说明捕获到了帧，订阅还需通过这些条件。</li><li><code>confRev</code> 用于提示配置版本是否一致。若报文已匹配但数据成员含义不符，核对 DataSet 引用、成员顺序和配置版本。</li></ul><h2 id="本机自发自收验证" tabindex="-1">本机自发自收验证 <a class="header-anchor" href="#本机自发自收验证" aria-label="Permalink to &quot;本机自发自收验证&quot;">​</a></h2><h3 id="配置发布与订阅" tabindex="-1">配置发布与订阅 <a class="header-anchor" href="#配置发布与订阅" aria-label="Permalink to &quot;配置发布与订阅&quot;">​</a></h3><ol><li>在测试网段中打开已加载模型的 IEC 61850 设备，选择一条已配置 DataSet 的 GOOSE 发布项。</li><li>发布和订阅选同一块已启用的以太网网卡。Linux 可用 <code>ip -br link</code> 查网卡名称。Windows 可用 <code>Get-NetAdapter</code> 查适配器名称和状态。容器或虚拟机内的后端需要使用其自身可见的网卡。</li><li>从发布配置复制实际的 GoCBRef、APPID 和目的组播 MAC。例如 GoCBRef 可以是 <code>IED1LD0/LLN0$GO$gcb1</code>。填写订阅后先启用本地接收，再启动发布。</li><li>查看订阅的最新数据和接收历史。周期重发时，接收计数应递增，<code>stNum</code> 通常保持稳定，<code>sqNum</code> 递增。变更一个发布成员值后，检查订阅值和 <code>stNum</code> 是否更新。</li><li>在 Linux 上先用 VID <code>0</code> 验证默认的优先级标签，再在允许该 VLAN 的测试网段验证非零 VID。Windows 可分别验证 VID <code>0</code> 的无标签帧和非零 VID 的带标签帧。</li></ol><h3 id="linux-抓包" tabindex="-1">Linux 抓包 <a class="header-anchor" href="#linux-抓包" aria-label="Permalink to &quot;Linux 抓包&quot;">​</a></h3><p>将 <code>eth0</code> 替换为后端所用的网卡名。使用 <code>-Q out</code> 查看本机出站帧，省略该选项可同时观察入站和出站流量。 <a href="https://github.com/the-tcpdump-group/tcpdump/blob/master/tcpdump.1.in" target="_blank" rel="noreferrer">tcpdump 手册源码</a></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ni</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> out</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;ether proto 0x88b8 or (vlan and ether proto 0x88b8)&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>预期能看到与发布配置一致的目的 MAC。带标签的帧通常会显示 <code>802.1Q</code>、VLAN ID 和优先级，内层协议为 <code>0x88b8</code>。该命令以提升后的权限运行，应用后端进程的套接字权限需要单独核对。若只看到本机出站帧，可在另一台测试主机或交换机镜像口确认线上是否收到。</p><h3 id="windows-抓包" tabindex="-1">Windows 抓包 <a class="header-anchor" href="#windows-抓包" aria-label="Permalink to &quot;Windows 抓包&quot;">​</a></h3><p>在 Wireshark 中选择与 EMS Simulate 相同的以太网适配器，开始抓包后使用显示过滤器 <code>goose</code>。要缩小范围，可用 <code>goose.appid == 0x0001</code> 并替换为实际 APPID。展开以太网、802.1Q 和 GOOSE 层，核对目的 MAC、标签和 GoCBRef。 <a href="https://www.wireshark.org/docs/dfref/g/goose.html" target="_blank" rel="noreferrer">Wireshark GOOSE 显示过滤器参考</a></p><p>如果后端无法打开适配器，先检查 Npcap 驱动和安装时的访问设置，再重新启动后端。 <a href="https://npcap.com/guide/npcap-users-guide.html" target="_blank" rel="noreferrer">Npcap 用户指南</a></p><p>驱动或网卡可能移除 VLAN 标签，导致本机抓包看不到标签。需要确认线上的标签时，可使用能保留 VLAN 标签的对端抓包接口，或使用保留标签的交换机镜像口。 <a href="https://wiki.wireshark.org/CaptureSetup/VLAN" target="_blank" rel="noreferrer">Wireshark VLAN 抓包说明</a></p><h2 id="按现象定位" tabindex="-1">按现象定位 <a class="header-anchor" href="#按现象定位" aria-label="Permalink to &quot;按现象定位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现场现象</th><th>核对顺序</th></tr></thead><tbody><tr><td>启动接收时提示原始套接字权限不足</td><td>Linux 核对实际后端进程的 <code>CAP_NET_RAW</code> 及其网络命名空间。Windows 核对 Npcap 驱动、访问权限和所选适配器</td></tr><tr><td>指定网卡抓不到本机发布帧</td><td>确认发布已启用、选中的网卡处于可用状态、抓包绑定同一网卡，再检查发布日志。发布状态和抓到实际帧是两项独立证据</td></tr><tr><td>旧版 Linux 能抓到带标签的出站帧，订阅计数为零</td><td>确认是否仍在使用 libiec61850 接收路径。更新含本修复的后端后，启动日志应显示 <code>GOOSE Receiver 已启动 (AF_PACKET)</code></td></tr><tr><td>更新后能抓到帧，订阅计数仍为零</td><td>核对本地订阅已启用，订阅网卡一致，<code>goCbRef</code> 完全相同，APPID 和目的 MAC 与帧一致</td></tr><tr><td>订阅有接收记录，成员值或版本不符</td><td>比对帧中的 <code>datSet</code>、<code>confRev</code>、成员个数及顺序，检查订阅使用的 SCL 模型</td></tr><tr><td>本机自收正常，对端仍收不到</td><td>在对端或交换机镜像口抓包，核对端口 VLAN、标签处理和二层组播转发。自收只验证本机发布与订阅链路</td></tr></tbody></table><h2 id="自动化验证范围" tabindex="-1">自动化验证范围 <a class="header-anchor" href="#自动化验证范围" aria-label="Permalink to &quot;自动化验证范围&quot;">​</a></h2><p>回归测试模拟 Linux 原始套接字，分别注入无标签帧、VID <code>0</code> 优先级标签帧和 VID <code>100</code> 帧。测试检查绑定的网卡、订阅匹配、数据集历史和事件时标，并验证短帧以及 APPID 或目的 MAC 不匹配的帧不会更新订阅。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/protocols/iec61850/goose/test_capture_subscriber.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>该测试覆盖应用的收包和解析流程。网卡驱动是否提供出站帧副本，以及跨主机的 VLAN 标签和转发行为，需要按上面的实机步骤验证。</p>`,33)])])}const b=a(d,[["render",o]]);export{u as __pageData,b as default};
